INSERT OR REPLACE INTO app_config (key, value) VALUES
  ('industries', '{"peptide":{"label":"Peptides & Research Chemicals","description":"Standard compliance, legal, and operational document requirements for peptide and research chemical merchants.","intro":"Welcome to AHG Pay — the payments and growth partner for peptide and research chemical brands. Submit the required corporate records, bank statements, and lab/compliance verification items below.","licensingNote":"Peptide vendor invoices, safety data sheets (SDS if no COAs), 3PL fulfillment agreements, and website research compliance disclaimers. Contact for West Town Checking Accounts: Ross Sloan (rsloan@dartbank.com), Caitlin Berlin (cberlin@dartbank.com).","sections":[{"id":"corporate","title":"Corporate & Identity Documents","description":"Essential legal identification for business entity and owners.","documents":[{"type":101,"name":"Articles of Incorporation","description":"State-filed formation document.","required":true,"tag":null},{"type":102,"name":"SS-4 / EIN Letter","description":"Official IRS tax ID confirmation.","required":true,"tag":null},{"type":103,"name":"Voided Check or Bank Letter","description":"Pre-printed check or signed bank officer letter for settlements.","required":true,"tag":null},{"type":104,"name":"Driver''s Licenses (up to 4)","description":"Color photo ID for all 25%+ equity owners.","required":true,"tag":null},{"type":105,"name":"Operating Agreement (LLC) / Bylaws (Corp)","description":"Internal governance and signatory authority docs.","required":false,"tag":null}]},{"id":"financial","title":"Financial & Processing History","description":"Required to establish volume tiers and underwriting limits.","documents":[{"type":201,"name":"Bank Statements (Last 3 Months)","description":"All pages of primary operating account (personal if no business).","required":true,"tag":null},{"type":202,"name":"Processing Statements (Last 3 Months)","description":"Current/prior merchant processing history (or N/A).","required":false,"tag":null},{"typ