":"Color photo ID for all 25%+ equity owners.","required":true,"tag":null},{"type":105,"name":"Operating Agreement (LLC) / Bylaws (Corp)","description":"Internal governance and signatory authority docs.","required":false,"tag":null}]},{"id":"financial","title":"Financial & Processing History","description":"Required to establish volume tiers and underwriting limits.","documents":[{"type":201,"name":"Bank Statements (Last 3 Months)","description":"All pages of primary operating account (personal if no business).","required":true,"tag":null},{"type":202,"name":"Processing Statements (Last 3 Months)","description":"Current/prior merchant processing history (if available).","required":false,"tag":null},{"type":203,"name":"Financial Statements / Tax Returns (2 Years)","description":"Balance sheet, P&L, or signed tax filings for high limits.","required":false,"tag":null}]},{"id":"hemp_compliance","title":"Hemp / CBD Compliance Verification","description":"Mandatory agricultural and lab testing documentation.","documents":[{"type":401,"name":"Full Panel Lab COAs (Last 12-23 Months)","description":"Third-party lab certificates of analysis showing < 0.3% Delta-9 THC (12 months for West Town, 23 months for Argyle).","required":true,"tag":null},{"type":402,"name":"Hemp License OR Hemp Food Permit","description":"State Department of Agriculture license or registration (mandatory for edibles in CO, CT, FL, TX, GA, IA, ME, MI, RI).","required":true,"tag":null},{"type":309,"name":"Product List for eComm / COA Zip File for Retail","description":"Complete product catalog of all alternative products (CBD, THC, hemp) or retail COA ZIP file.","required":true,"tag":null},{"type":301,"name":"Website Compliance & FDA Attestation","description":"Terms of Service, Privacy Policy, and Refund Policy matching legal entity; phone & email in contact area; mandatory FDA footer statement: ''These statements have not been evaluated by the FDA. Products are not intended to diagnose, treat, cure, or prevent any disease. Products contain <0.3% Delta-9 THC, compliant with 2018 Farm Bill. Consult healthcare provider before use if pregnant, nursing, taking medications, or have medical conditions. Use responsibly.''","required":true,"tag":null},{"type":302,"name":"Fulfillment Agreement / 3PL Contract","description":"Proof of warehousing and fulfillment logistics (if using 3PL).","required":false,"tag":null},{"type":303,"name":"Site & Inventory Photos","description":"Photos of inventory, storage, and packaging facility.","required":false,"tag":null},{"type":307,"name":"Proof of Domain Ownership","description":"Registrar receipt showing company as registrant.","required":true,"tag":null}]},{"id":"signatures","title":"Required Signatures & Addenda","description":"Standard merchant agreements requiring verified e-signatures.","documents":[{"type":501,"name":"Compliance Monitoring Agreement","description":"Monthly third-party web compliance scan authorization.","required":true,"tag":"Signature Doc"},{"type":502,"name":"Reserve & Settlement Schedule Acknowledgement","description":"Rolling reserve policy terms and sign-off.","required":true,"tag":"Signature Doc"},{"type":504,"name":"WTP Sole Member Affidavit","description":"Required for single-member LLCs or sole proprietorships.","required":false,"tag":"Signature Doc"},{"type":507,"name":"Argyle Hemp EDD Worksheet","description":"Enhanced due diligence worksheet for Argyle processing.","required":false,"tag":"Signature Doc"},{"type":508,"name":"Argyle File Build Form","description":"Retail setup form with physical card terminal (if applicable).","required":false,"tag":"Signature Doc"},{"type":509,"name":"Argyle Free Terminal Form","description":"Free terminal agreement (if marked by sales).","required":false,"tag":"Signature Doc"},{"type":511,"name":"Argyle NABCO Cross-Corp Agreement","description":"Cross-corporate indemnity for multiple related entities.","required":false,"tag":"Signature Doc"}]}]},"general":{"label":"Ge